mapper.select:
SELECT e.alert_event_id,e.integration_id,i.integration_code,i.integration_name,e.external_event_id,e.event_type,e.fingerprint,e.alert_cycle_ref AS cycle_ref,e.occurred_at,e.received_at,e.disposition,e.incident_id,e.raw_body_sha256,e.summary,e.correlation_id
FROM alert_event e JOIN monitoring_integration i ON i.tenant_id=e.tenant_id AND i.integration_id=e.integration_id WHERE e.tenant_id=#{tenantId}
AND e.event_type=#{filter.eventType}

  AND e.disposition='REVIEW_REQUIRED' AND NOT ()
  AND (e.disposition='APPLIED' OR (e.incident_id IS NULL AND ()))
  AND e.disposition=#{filter.disposition}

AND (e.incident_id=#{filter.incidentId} OR (e.incident_id IS NULL AND EXISTS (SELECT 1 FROM incident linked JOIN alert_event first_event ON first_event.tenant_id=linked.tenant_id AND first_event.alert_event_id=linked.first_event_id WHERE linked.tenant_id=#{tenantId} AND linked.incident_id=#{filter.incidentId} AND linked.fingerprint=e.fingerprint AND first_event.alert_cycle_ref=e.alert_cycle_ref)))
AND e.fingerprint=#{filter.fingerprint}
AND e.alert_cycle_ref=#{filter.cycleRef}
AND e.external_event_id=#{filter.externalEventId}
AND e.received_at >= #{filter.receivedFrom}
AND e.received_at <= #{filter.receivedTo}
AND ( >< #{cursorTime} OR (=#{cursorTime} AND e.alert_event_id >< #{cursorId}))
ORDER BY  ASCDESC,e.alert_event_id ASCDESC LIMIT #{limit}
